static void aw_Galactic_process_fast(void *aw_state, int16_t *aw_out,
    const int16_t *aw_in, int32_t sampleFrames, uint32_t aw_channels) {
    aw_Galactic_fast_t *aw_s = (aw_Galactic_fast_t *)aw_state;
    const double aw_sample_rate = aw_s->aw_sample_rate;
    (void)aw_sample_rate;
    float iirAL = aw_s->iirAL;
    float iirBL = aw_s->iirBL;
    float *aIL = aw_s->aIL;
    float *aJL = aw_s->aJL;
    float *aKL = aw_s->aKL;
    float *aLL = aw_s->aLL;
    float *aAL = aw_s->aAL;
    float *aBL = aw_s->aBL;
    float *aCL = aw_s->aCL;
    float *aDL = aw_s->aDL;
    float *aEL = aw_s->aEL;
    float *aFL = aw_s->aFL;
    float *aGL = aw_s->aGL;
    float *aHL = aw_s->aHL;
    float *aML = aw_s->aML;
    float *aMR = aw_s->aMR;
    double oldfpd = aw_s->oldfpd;
    float feedbackAL = aw_s->feedbackAL;
    float feedbackBL = aw_s->feedbackBL;
    float feedbackCL = aw_s->feedbackCL;
    float feedbackDL = aw_s->feedbackDL;
    float *lastRefL = aw_s->lastRefL;
    float iirAR = aw_s->iirAR;
    float iirBR = aw_s->iirBR;
    float *aIR = aw_s->aIR;
    float *aJR = aw_s->aJR;
    float *aKR = aw_s->aKR;
    float *aLR = aw_s->aLR;
    float *aAR = aw_s->aAR;
    float *aBR = aw_s->aBR;
    float *aCR = aw_s->aCR;
    float *aDR = aw_s->aDR;
    float *aER = aw_s->aER;
    float *aFR = aw_s->aFR;
    float *aGR = aw_s->aGR;
    float *aHR = aw_s->aHR;
    float feedbackAR = aw_s->feedbackAR;
    float feedbackBR = aw_s->feedbackBR;
    float feedbackCR = aw_s->feedbackCR;
    float feedbackDR = aw_s->feedbackDR;
    float *lastRefR = aw_s->lastRefR;
    int countA = aw_s->countA;
    int delayA = aw_s->delayA;
    int countB = aw_s->countB;
    int delayB = aw_s->delayB;
    int countC = aw_s->countC;
    int delayC = aw_s->delayC;
    int countD = aw_s->countD;
    int delayD = aw_s->delayD;
    int countE = aw_s->countE;
    int delayE = aw_s->delayE;
    int countF = aw_s->countF;
    int delayF = aw_s->delayF;
    int countG = aw_s->countG;
    int delayG = aw_s->delayG;
    int countH = aw_s->countH;
    int delayH = aw_s->delayH;
    int countI = aw_s->countI;
    int delayI = aw_s->delayI;
    int countJ = aw_s->countJ;
    int delayJ = aw_s->delayJ;
    int countK = aw_s->countK;
    int delayK = aw_s->delayK;
    int countL = aw_s->countL;
    int delayL = aw_s->delayL;
    int countM = aw_s->countM;
    int delayM = aw_s->delayM;
    int cycle = aw_s->cycle;
    uint64_t vibM = aw_s->vibM;
    uint32_t fpdL = aw_s->fpdL;
    uint32_t fpdR = aw_s->fpdR;
    float A = aw_s->A;
    float B = aw_s->B;
    float C = aw_s->C;
    float D = aw_s->D;
    float E = aw_s->E;
    {

	double overallscale = 1.0;
	overallscale /= 44100.0;
	overallscale *= aw_sample_rate;
	
	int cycleEnd = floor(overallscale);
	if (cycleEnd < 1) cycleEnd = 1;
	if (cycleEnd > 4) cycleEnd = 4;
	//this is going to be 2 for 88.1 or 96k, 3 for silly people, 4 for 176 or 192k
	if (cycle > cycleEnd-1) cycle = cycleEnd-1; //sanity check
	
	double regen = 0.0625+((1.0-A)*0.0625);
	double attenuate = (1.0 - (regen / 0.125))*1.333;
	double lowpass = pow(1.00001-(1.0-B),2.0)/sqrt(overallscale);
	double drift = pow(C,3)*0.001;
	double size = (D*1.77)+0.1;
	double wet = 1.0-(pow(1.0-E,3));
	
	delayI = 3407.0*size;
	delayJ = 1823.0*size;
	delayK = 859.0*size;
	delayL = 331.0*size;
	delayA = 4801.0*size;
	delayB = 2909.0*size;
	delayC = 1153.0*size;
	delayD = 461.0*size;
	delayE = 7607.0*size;
	delayF = 4217.0*size;
	delayG = 2269.0*size;
	delayH = 1597.0*size;
	delayM = 256;
	
    const float aw_f_regen = (float)regen;
	const float aw_f_attenuate = (float)attenuate;
	const float aw_f_lowpass = (float)lowpass;
	const float aw_f_wet = (float)wet;
	uint64_t aw_step_vibM = AW_Q60_STEP((oldfpd*drift));
	const float aw_inv0 = 1.0f / (2.0f);
	const float aw_inv1 = 1.0f / (8.0f);
	const float aw_inv2 = 1.0f / (2);
	const float aw_inv3 = 1.0f / (3);
	while (--sampleFrames >= 0)
    {
		const float aw_inL = AW_IN_L(aw_in);
		const float aw_inR = AW_IN_R(aw_in, aw_channels);
		float aw_outL = 0.0f, aw_outR = 0.0f;/* aw:loop */
		float inputSampleL = aw_inL;
		float inputSampleR = aw_inR;
		if (fabsf(inputSampleL)<1.18e-23f) inputSampleL = fpdL * 1.18e-17f;
		if (fabsf(inputSampleR)<1.18e-23f) inputSampleR = fpdR * 1.18e-17f;
		float drySampleL = inputSampleL;
		float drySampleR = inputSampleR;
		
		vibM += aw_step_vibM;
		if (vibM > AW_Q60(3.141592653589793238*2.0)) {
			vibM = AW_Q60(0.0);
			oldfpd = 0.4294967295+(fpdL*0.0000000000618);
			aw_step_vibM = AW_Q60_STEP((oldfpd*drift));
		}
		
		aML[countM] = inputSampleL * aw_f_attenuate;
		aMR[countM] = inputSampleR * aw_f_attenuate;
		countM++; if (countM < 0 || countM > delayM) countM = 0;
		
		float offsetML = (aw_sinf(aw_q60f(vibM))+1.0f)*127;
		float offsetMR = (aw_sinf(aw_q60f(vibM)+(3.141592653589793238f* aw_inv0))+1.0f)*127;
		int workingML = countM  + (int)aw_floorf( offsetML);
		int workingMR = countM  + (int)aw_floorf( offsetMR);
		float interpolML = (aML[workingML-((workingML > delayM)?delayM+1:0)] * (1-(offsetML-aw_floorf(offsetML))));
		interpolML += (aML[workingML+1-((workingML+1 > delayM)?delayM+1:0)] * ((offsetML-aw_floorf(offsetML))) );
		float interpolMR = (aMR[workingMR-((workingMR > delayM)?delayM+1:0)] * (1-(offsetMR-aw_floorf(offsetMR))));
		interpolMR += (aMR[workingMR+1-((workingMR+1 > delayM)?delayM+1:0)] * ((offsetMR-aw_floorf(offsetMR))) );
		inputSampleL = interpolML;
		inputSampleR = interpolMR;
		//predelay that applies vibrato
		//want vibrato speed AND depth like in MatrixVerb
		
		iirAL = (iirAL*(1.0f-aw_f_lowpass))+(inputSampleL*aw_f_lowpass); inputSampleL = iirAL;
		iirAR = (iirAR*(1.0f-aw_f_lowpass))+(inputSampleR*aw_f_lowpass); inputSampleR = iirAR;
		//initial filter
		
		cycle++;
		if (cycle == cycleEnd) { //hit the end point and we do a reverb sample
			aIL[countI] = inputSampleL + (feedbackAR * aw_f_regen);
			aJL[countJ] = inputSampleL + (feedbackBR * aw_f_regen);
			aKL[countK] = inputSampleL + (feedbackCR * aw_f_regen);
			aLL[countL] = inputSampleL + (feedbackDR * aw_f_regen);
			aIR[countI] = inputSampleR + (feedbackAL * aw_f_regen);
			aJR[countJ] = inputSampleR + (feedbackBL * aw_f_regen);
			aKR[countK] = inputSampleR + (feedbackCL * aw_f_regen);
			aLR[countL] = inputSampleR + (feedbackDL * aw_f_regen);
			
			countI++; if (countI < 0 || countI > delayI) countI = 0;
			countJ++; if (countJ < 0 || countJ > delayJ) countJ = 0;
			countK++; if (countK < 0 || countK > delayK) countK = 0;
			countL++; if (countL < 0 || countL > delayL) countL = 0;
			
			float outIL = aIL[countI-((countI > delayI)?delayI+1:0)];
			float outJL = aJL[countJ-((countJ > delayJ)?delayJ+1:0)];
			float outKL = aKL[countK-((countK > delayK)?delayK+1:0)];
			float outLL = aLL[countL-((countL > delayL)?delayL+1:0)];
			float outIR = aIR[countI-((countI > delayI)?delayI+1:0)];
			float outJR = aJR[countJ-((countJ > delayJ)?delayJ+1:0)];
			float outKR = aKR[countK-((countK > delayK)?delayK+1:0)];
			float outLR = aLR[countL-((countL > delayL)?delayL+1:0)];
			//first block: now we have four outputs
			
			aAL[countA] = (outIL - (outJL + outKL + outLL));
			aBL[countB] = (outJL - (outIL + outKL + outLL));
			aCL[countC] = (outKL - (outIL + outJL + outLL));
			aDL[countD] = (outLL - (outIL + outJL + outKL));
			aAR[countA] = (outIR - (outJR + outKR + outLR));
			aBR[countB] = (outJR - (outIR + outKR + outLR));
			aCR[countC] = (outKR - (outIR + outJR + outLR));
			aDR[countD] = (outLR - (outIR + outJR + outKR));
			
			countA++; if (countA < 0 || countA > delayA) countA = 0;
			countB++; if (countB < 0 || countB > delayB) countB = 0;
			countC++; if (countC < 0 || countC > delayC) countC = 0;
			countD++; if (countD < 0 || countD > delayD) countD = 0;
			
			float outAL = aAL[countA-((countA > delayA)?delayA+1:0)];
			float outBL = aBL[countB-((countB > delayB)?delayB+1:0)];
			float outCL = aCL[countC-((countC > delayC)?delayC+1:0)];
			float outDL = aDL[countD-((countD > delayD)?delayD+1:0)];
			float outAR = aAR[countA-((countA > delayA)?delayA+1:0)];
			float outBR = aBR[countB-((countB > delayB)?delayB+1:0)];
			float outCR = aCR[countC-((countC > delayC)?delayC+1:0)];
			float outDR = aDR[countD-((countD > delayD)?delayD+1:0)];
			//second block: four more outputs
			
			aEL[countE] = (outAL - (outBL + outCL + outDL));
			aFL[countF] = (outBL - (outAL + outCL + outDL));
			aGL[countG] = (outCL - (outAL + outBL + outDL));
			aHL[countH] = (outDL - (outAL + outBL + outCL));
			aER[countE] = (outAR - (outBR + outCR + outDR));
			aFR[countF] = (outBR - (outAR + outCR + outDR));
			aGR[countG] = (outCR - (outAR + outBR + outDR));
			aHR[countH] = (outDR - (outAR + outBR + outCR));
			
			countE++; if (countE < 0 || countE > delayE) countE = 0;
			countF++; if (countF < 0 || countF > delayF) countF = 0;
			countG++; if (countG < 0 || countG > delayG) countG = 0;
			countH++; if (countH < 0 || countH > delayH) countH = 0;
			
			float outEL = aEL[countE-((countE > delayE)?delayE+1:0)];
			float outFL = aFL[countF-((countF > delayF)?delayF+1:0)];
			float outGL = aGL[countG-((countG > delayG)?delayG+1:0)];
			float outHL = aHL[countH-((countH > delayH)?delayH+1:0)];
			float outER = aER[countE-((countE > delayE)?delayE+1:0)];
			float outFR = aFR[countF-((countF > delayF)?delayF+1:0)];
			float outGR = aGR[countG-((countG > delayG)?delayG+1:0)];
			float outHR = aHR[countH-((countH > delayH)?delayH+1:0)];
			//third block: final outputs
			
			feedbackAL = (outEL - (outFL + outGL + outHL));
			feedbackBL = (outFL - (outEL + outGL + outHL));
			feedbackCL = (outGL - (outEL + outFL + outHL));
			feedbackDL = (outHL - (outEL + outFL + outGL));
			feedbackAR = (outER - (outFR + outGR + outHR));
			feedbackBR = (outFR - (outER + outGR + outHR));
			feedbackCR = (outGR - (outER + outFR + outHR));
			feedbackDR = (outHR - (outER + outFR + outGR));
			//which we need to feed back into the input again, a bit
			
			inputSampleL = (outEL + outFL + outGL + outHL)* aw_inv1;
			inputSampleR = (outER + outFR + outGR + outHR)* aw_inv1;
			//and take the final combined sum of outputs
			if (cycleEnd == 4) {
				lastRefL[0] = lastRefL[4]; //start from previous last
				lastRefL[2] = (lastRefL[0] + inputSampleL)* aw_inv2; //half
				lastRefL[1] = (lastRefL[0] + lastRefL[2])* aw_inv2; //one quarter
				lastRefL[3] = (lastRefL[2] + inputSampleL)* aw_inv2; //three quarters
				lastRefL[4] = inputSampleL; //full
				lastRefR[0] = lastRefR[4]; //start from previous last
				lastRefR[2] = (lastRefR[0] + inputSampleR)* aw_inv2; //half
				lastRefR[1] = (lastRefR[0] + lastRefR[2])* aw_inv2; //one quarter
				lastRefR[3] = (lastRefR[2] + inputSampleR)* aw_inv2; //three quarters
				lastRefR[4] = inputSampleR; //full
			}
			if (cycleEnd == 3) {
				lastRefL[0] = lastRefL[3]; //start from previous last
				lastRefL[2] = (lastRefL[0]+lastRefL[0]+inputSampleL)* aw_inv3; //third
				lastRefL[1] = (lastRefL[0]+inputSampleL+inputSampleL)* aw_inv3; //two thirds
				lastRefL[3] = inputSampleL; //full
				lastRefR[0] = lastRefR[3]; //start from previous last
				lastRefR[2] = (lastRefR[0]+lastRefR[0]+inputSampleR)* aw_inv3; //third
				lastRefR[1] = (lastRefR[0]+inputSampleR+inputSampleR)* aw_inv3; //two thirds
				lastRefR[3] = inputSampleR; //full
			}
			if (cycleEnd == 2) {
				lastRefL[0] = lastRefL[2]; //start from previous last
				lastRefL[1] = (lastRefL[0] + inputSampleL)* aw_inv2; //half
				lastRefL[2] = inputSampleL; //full
				lastRefR[0] = lastRefR[2]; //start from previous last
				lastRefR[1] = (lastRefR[0] + inputSampleR)* aw_inv2; //half
				lastRefR[2] = inputSampleR; //full
			}
			if (cycleEnd == 1) {
				lastRefL[0] = inputSampleL;
				lastRefR[0] = inputSampleR;
			}
			cycle = 0; //reset
			inputSampleL = lastRefL[cycle];
			inputSampleR = lastRefR[cycle];
		} else {
			inputSampleL = lastRefL[cycle];
			inputSampleR = lastRefR[cycle];
			//we are going through our references now
		}
		
		iirBL = (iirBL*(1.0f-aw_f_lowpass))+(inputSampleL*aw_f_lowpass); inputSampleL = iirBL;
		iirBR = (iirBR*(1.0f-aw_f_lowpass))+(inputSampleR*aw_f_lowpass); inputSampleR = iirBR;
		//end filter
		
		if (aw_f_wet < 1.0f) {
			inputSampleL = (inputSampleL * aw_f_wet) + (drySampleL * (1.0f-aw_f_wet));
			inputSampleR = (inputSampleR * aw_f_wet) + (drySampleR * (1.0f-aw_f_wet));
		}
		fpdL ^= fpdL << 13; fpdL ^= fpdL >> 17; fpdL ^= fpdL << 5;
		fpdR ^= fpdR << 13; fpdR ^= fpdR >> 17; fpdR ^= fpdR << 5;
		//end 32 bit stereo floating point dither
		
		aw_outL = inputSampleL;
		aw_outR = inputSampleR;
    /* aw:end */		AW_OUT_FAST(aw_out, aw_channels, aw_outL, aw_outR);
		aw_in += aw_channels;
		aw_out += aw_channels;
	}
}
    aw_s->iirAL = iirAL;
    aw_s->iirBL = iirBL;
    aw_s->oldfpd = oldfpd;
    aw_s->feedbackAL = feedbackAL;
    aw_s->feedbackBL = feedbackBL;
    aw_s->feedbackCL = feedbackCL;
    aw_s->feedbackDL = feedbackDL;
    aw_s->iirAR = iirAR;
    aw_s->iirBR = iirBR;
    aw_s->feedbackAR = feedbackAR;
    aw_s->feedbackBR = feedbackBR;
    aw_s->feedbackCR = feedbackCR;
    aw_s->feedbackDR = feedbackDR;
    aw_s->countA = countA;
    aw_s->delayA = delayA;
    aw_s->countB = countB;
    aw_s->delayB = delayB;
    aw_s->countC = countC;
    aw_s->delayC = delayC;
    aw_s->countD = countD;
    aw_s->delayD = delayD;
    aw_s->countE = countE;
    aw_s->delayE = delayE;
    aw_s->countF = countF;
    aw_s->delayF = delayF;
    aw_s->countG = countG;
    aw_s->delayG = delayG;
    aw_s->countH = countH;
    aw_s->delayH = delayH;
    aw_s->countI = countI;
    aw_s->delayI = delayI;
    aw_s->countJ = countJ;
    aw_s->delayJ = delayJ;
    aw_s->countK = countK;
    aw_s->delayK = delayK;
    aw_s->countL = countL;
    aw_s->delayL = delayL;
    aw_s->countM = countM;
    aw_s->delayM = delayM;
    aw_s->cycle = cycle;
    aw_s->vibM = vibM;
    aw_s->fpdL = fpdL;
    aw_s->fpdR = fpdR;
}

